#!/usr/bin/env bash
# Run Android x86_64 test binaries against our vendor HALs and drivers without
# booting Android.
#
#   tests/bionic/run.sh [-e VAR=val]... [-v VENDOR_DIR]... [-t TEST_DIR] -- PROG [ARGS...]
#
# The root comes from the session's image (`linuxapk-session image`): its
# /system, /system_ext, /product and flattened /apex, with /vendor = the
# stage's under any -v layers (first on top), and a /linkerconfig
# generated by the image's own linkerconfig. -t binds TEST_DIR at
# /data/nativetest64, which linkerconfig puts in the [system] section, as for
# a platform test. The session's pivot-exec runs tests/bionic/init.sh there
# behind the seccomp filter, with the broker serving binder, and init.sh
# starts servicemanager, our allocator and our composer, then runs PROG.
#
# There is no init, logd or property service: the props shim (props-shim.c,
# preloaded everywhere) mirrors logs to stderr and serves LINUXAPK_PROPS
# ("name=value;...", set with -e). -e exports to every process.
#
# TIMEOUT=<s> (default 300) bounds PROG. The run is a transient systemd user
# unit with a memory cap. The composer's frame dumps land in
# out/test/bionic/frames.
#
# Host safety (AGENTS.md): besides lib.sh's root, /dev gets udmabuf and the
# render nodes (no card*/KMS), and /sys only read-only binds of what
# libdrm/Mesa read: each render node's PCI device dir, its /sys/dev/char
# link, and the CPU topology.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
# shellcheck source=lib.sh
. "$here/lib.sh"
timeout=${TIMEOUT:-300}

if [[ ${1:-} == --inner ]]; then
  shift
else
  bionic_prepare
  mkdir -p "$scratch/frames"
  bionic_unit linuxapk-bionictest $((timeout + 60)) -E TIMEOUT="$timeout" -- "$@"
  exit
fi

img=$BIONIC_IMG apex=$BIONIC_APEX
envs=() vendor=() tests=""
while (($#)); do
  case $1 in
    -e) envs+=("$2") ;;
    -v) vendor+=("$(realpath "$2")") ;;
    -t) tests=$(realpath "$2") ;;
    --)
      shift
      break
      ;;
    *) break ;;
  esac
  shift 2
done
(($#)) || {
  echo "usage: tests/bionic/run.sh [-e VAR=val]... [-v VENDOR_DIR]... [-t TEST_DIR] -- PROG [ARGS...]" >&2
  exit 2
}

# The root is a tmpfs in this private mount namespace, so concurrent runs can
# share the mount point.
R=$scratch/root
base=$scratch/vendor-base
mkdir -p "$base/etc/vintf"
# libvintf ignores manifest fragments (our allocator's) without a base device
# manifest; in a session the image's vendor manifest is that base.
echo '<manifest version="1.0" type="device" target-level="202604"/>' >"$base/etc/vintf/manifest.xml"
bionic_root "$R" "${vendor[@]}" "$stage_vendor" "$base"
bionic_broker_nodes "$R"
cp "$here/init.sh" "$R/init.sh"
mkdir -p "$R/data/nativetest64" "$R/data/vendor/linuxapk/frames"
[[ -z $tests ]] || ro_bind "$tests" "$R/data/nativetest64"
mount --bind "$scratch/frames" "$R/data/vendor/linuxapk/frames"
cp "$broker" "$R/data/local/tmp/"

for n in /dev/udmabuf /dev/dri/renderD*; do
  [[ -e $n ]] || continue
  mkdir -p "$R$(dirname "$n")"
  touch "$R$n"
  mount --bind "$n" "$R$n"
done
mkdir -p "$R/sys/dev/char" "$R/sys/devices/system/cpu"
for n in /dev/dri/renderD*; do
  [[ -e $n ]] || continue
  majmin=$(printf '%d:%d' "0x$(stat -c %t "$n")" "0x$(stat -c %T "$n")")
  node=$(readlink -f "/sys/dev/char/$majmin") # .../<pci dev>/drm/renderD128
  pcidev=${node%/drm/*}
  mkdir -p "$R$pcidev"
  ro_bind "$pcidev" "$R$pcidev"
  ln -s "$node" "$R/sys/dev/char/$majmin"
done
ro_bind /sys/devices/system/cpu "$R/sys/devices/system/cpu"

bionic_env
for e in "${envs[@]}"; do export "${e?}"; done
export LINUXAPK_BROKER=/data/local/tmp/linuxapk-broker TIMEOUT=$timeout
exec "$pivot_exec" "$R" /system/bin/sh /init.sh "$@"
